arguments.command:
python3 -c "
import json
with open('/app/resources/treasury_bulletin_2017_06.json') as f:
    data = json.load(f)
doc = data.get('document', {})
pages = doc.get('pages', [])
for i, page in enumerate(pages):
    for el in page.get('elements', []):
        if isinstance(el, dict):
            content = el.get('content', '')
            if isinstance(content, str) and ('Continental Shelf' in content or 'OCS' in content):
                print(f'Page {i+1}: {content[:200]}')
"
